func RulesBySeverity(severity string) []OperationalRule { out := []OperationalRule{}; for _, r := range OperationalPlaybook { if r.Severity == severity { out = append(out, r) } }; return out }
func RulesByArea(area string) []OperationalRule { out := []OperationalRule{}; for _, r := range OperationalPlaybook { if r.Area == area { out = append(out, r) } }; return out }
func CriticalRuleCount() int { return len(RulesBySeverity("critical")) }
